head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > displayMode]<br/>컴포넌트의 아이템 리스트와 라벨 표시 영역에 아이템의 라벨값이 표시되는 포맷을 설정합니다.",
    "validation" : [
        "미설정 시 아이템의 Label 값이 라벨로 표시합니다.",
        "value delim label 설정 시 아이템의 Value 값과 Label 값을 구분자로 구분하여 순서대로 표시합니다.",
        "value delim value 설정 시 아이템의 Label 값과 Value 값을 구분자로 구분하여 순서대로 표시합니다.",
        "label 설정 시 아이템의 Label 값이 라벨로 표시합니다.",
        "value 설정 시 아이템의 Value 값이 라벨로 표시합니다.",
        "구분자는 delimiter 속성값을 사용하며 해당 속성을 설정하지 않으면 Tab('\\t')이 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        displayMode : con_displayMode.getText(),
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createBasicCheckComboBox(cList);
}


scwin.btn_getText_onclick = function (e) {
    let rtn = '';
    rtn = target1.getText();

    wf_body_bottom.getObj("scwin").setReturnValue("checkcombobox 의 label : " + rtn);   

    let comp = "target1_itemTable_main";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    if (targetElements.length == 0)
        wf_body_bottom.getObj("scwin").setReturnValue("CheckComboBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    let tds = targetElements[0].querySelectorAll('td.w2table_ccb_col');

    // 각 td 요소의 visible 확인
    tds.forEach((td, index) => {   
        let itemLabel = td.textContent;
        wf_body_bottom.getObj("scwin").setReturnValue("item index=" + index + " 의 label : " + itemLabel);	
    });	  
};
